behaviour_check.main_template:
#include <stdio.h>
#include <string.h>
#include "zlib.h"

#define PLAIN_LEN 4096u
#define PACKED_CAP 8192u
#define ROOM_SLACK 64u

static unsigned char plain[PLAIN_LEN];
static unsigned char squeezed[PACKED_CAP];
static unsigned char restored[PLAIN_LEN + ROOM_SLACK];

static void build_input(void) {
    unsigned i;
    for (i = 0; i < PLAIN_LEN; i++)
        plain[i] = (unsigned char)(65u + ((i * 7u + (i >> 5)) % 23u));
}

static int bail(const char *what, long detail) {
    fprintf(stderr, "roundtrip: %s (%ld)\n", what, detail);
    return 1;
}

int main(void) {
    z_stream packer;
    z_stream unpacker;
    uLong sum_plain, sum_restored;
    unsigned squeezed_len;
    int rc;

    build_input();
    sum_plain = crc32(0L, Z_NULL, 0);
    sum_plain = crc32(sum_plain, plain, PLAIN_LEN);
    if (sum_plain == 0)
        return bail("checksum of the input is zero", 0);

    memset(&packer, 0, sizeof(packer));
    rc = deflateInit(&packer, Z_DEFAULT_COMPRESSION);
    if (rc != Z_OK)
        return bail("compressor init refused", rc);
    packer.next_in = plain;
    packer.avail_in = PLAIN_LEN;
    packer.next_out = squeezed;
    packer.avail_out = PACKED_CAP;
    rc = deflate(&packer, Z_FINISH);
    if (rc != Z_STREAM_END)
        return bail("compressor did not finish in one call", rc);
    squeezed_len = (unsigned)packer.total_out;
    if (deflateEnd(&packer) != Z_OK)
        return bail("compressor teardown refused", 0);
    if (squeezed_len == 0 || squeezed_len >= PACKED_CAP)
        return bail("compressed length out of range", (long)squeezed_len);

    memset(&unpacker, 0, sizeof(unpacker));
    rc = inflateInit(&unpacker);
    if (rc != Z_OK)
        return bail("decompressor init refused", rc);
    unpacker.next_in = squeezed;
    unpacker.avail_in = squeezed_len;
    unpacker.next_out = restored;
    unpacker.avail_out = (uInt)sizeof(restored);
    rc = inflate(&unpacker, Z_FINISH);
    if (rc != Z_STREAM_END)
        return bail("decompressor did not reach end of stream", rc);
    if (unpacker.total_out != PLAIN_LEN)
        return bail("round trip length mismatch", (long)unpacker.total_out);
    if (inflateEnd(&unpacker) != Z_OK)
        return bail("decompressor teardown refused", 0);

    if (memcmp(plain, restored, PLAIN_LEN) != 0)
        return bail("round trip content mismatch", 0);

    sum_restored = crc32(0L, Z_NULL, 0);
    sum_restored = crc32(sum_restored, restored, PLAIN_LEN);
    if (sum_restored != sum_plain)
        return bail("checksum mismatch after round trip", (long)sum_restored);

    if (adler32(adler32(0L, Z_NULL, 0), plain, PLAIN_LEN) !=
        adler32(adler32(0L, Z_NULL, 0), restored, PLAIN_LEN))
        return bail("rolling checksum mismatch after round trip", 0);

    printf("roundtrip: ok %u -> %u -> %u\n", (unsigned)PLAIN_LEN,
           squeezed_len, (unsigned)unpacker.total_out);
    return 0;
}
